def cell(g):
    return [(i,j) for i,r in enumerate(g) for j,x in enumerate(r) if x]
print('demo out bbox cells rel:')
# For each comp in demo/test, compute bbox, count cells, and whether touches another comp (gap analysis via distance)
def analyze(name,g,out=None):
    cs=cell(g)
    # find comps with 4-conn
    seen=set(); res=[]
    H,W=len(g),len(g[0])
    for p,q in cs:
        if (p,q) in seen: continue
        st=[(p,q)]; c=[]
        while st:
            y,x=st.pop()
            if (y,x) in seen: continue
            seen.add((y,x)); c.append((y,x))
            for dy,dx in [(1,0),(-1,0),(0,1),(0,-1)]:
                ny,nx=y+dy,x+dx
                if 0<=ny<H and 0<=nx<W and g[ny][nx] and (ny,nx) not in seen: st.append((ny,nx))
        rs=[a for a,b in c]; cq=[b for a,b in c]
        sub=[[g[p][q] for q in range(min(cq),max(cq)+1)] for p in range(min(rs),max(rs)+1)]
        res.append({'cells':c,'bbox':(min(rs),min(cq),len(sub),len(sub[0])),'touching':False})
    # touching = bboxes overlap or within? use 8-neighborhood adjacency between comps
    n=len(res)
    for i in range(n):
        for j in range(i+1,n):
            ci, cj = res[i]['cells'],res[j]['cells']
            for (a,b) in ci:
                for (c2,d) in cj:
                    if abs(a-c2)<=1 and abs(b-d)<=1:
                        res[i]['touching']=res[j]['touching']=True
    for r in res: print(name, r['bbox'],'cells',len(r['cells']),'touching',r['touching'])
