def enc(s):
    R,C=len(s),len(s[0]); seen=set(); q=deque()
    for p in range(R):
        for cc in (0,C-1):
            if s[p][cc]==0 and (p,cc) not in seen: seen.add((p,cc)); q.append((p,cc))
    for cc in range(C):
        for p in (0,R-1):
            if s[p][cc]==0 and (p,cc) not in seen: seen.add((p,cc)); q.append((p,cc))
    while q:
        y,x=q.popleft()
        for dy,dx in [(1,0),(-1,0),(0,1),(0,-1)]:
            ny,nx=y+dy,x+dx
            if 0<=ny<R and 0<=nx<C and s[ny][nx]==0 and (ny,nx) not in seen: seen.add((ny,nx)); q.append((ny,nx))
    return sum(1 for r in range(R) for v in range(C) if s[r][v]==0 and (r,v) not in seen)
