def norm(s):
    pts={(i,j) for i,r in enumerate(s) for j,v in enumerate(r) if v}
    minr=min(p[0] for p in pts); minc=min(p[1] for p in pts)
    maxr=max(p[0] for p in pts); maxc=max(p[1] for p in pts)
    return tuple(''.join('#' if (i,minc+j) in pts else '.' for j in range(maxc-minc+1)) for i in range(minr,maxr+1))
def rots(S):
    cur=[list(r) for r in S]; res=[]
    for _ in range(4):
        res.append([list(r) for r in cur])
        cur=[list(r) for r in zip(*cur[::-1])]
    return res
